package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileTime;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.sketch.SketchBasedJoinEstimator;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class LmdbEstimatorRepeatedMarkerCommitTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:repeated-marker-commit:p");

	@Test
	void alreadyFencedSnapshotIsNotRewrittenForSubsequentCommits(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		seedSnapshot(directory);
		Files.copy(directory.resolve("join-estimator.rjes/synopsis-v8.bin"),
				evidence.resolve("original-v8-backup.bin"));
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(store.awaitSketchesReady(30, TimeUnit.SECONDS));
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			estimator.discardAndMarkForRebuild();
			Path marker = directory.resolve("join-estimator.rjes/synopsis-v8.rebuild");
			assertTrue(Files.isRegularFile(marker));
			Files.setLastModifiedTime(marker, FileTime.fromMillis(946684800000L));
			FileTime initial = Files.getLastModifiedTime(marker);
			FileTime first;
			FileTime second;
			long rows;
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:repeated-marker-commit:second"), P, VF.createLiteral(2));
				first = Files.getLastModifiedTime(marker);
				connection.add(VF.createIRI("urn:repeated-marker-commit:third"), P, VF.createLiteral(3));
				second = Files.getLastModifiedTime(marker);
				rows = connection.size();
			}
			assertAll("a valid marker already protects each subsequent commit",
					() -> assertTrue(Files.isRegularFile(marker)),
					() -> assertEquals(initial, first, "first commit must not rewrite the existing marker"),
					() -> assertEquals(initial, second, "second commit must not rewrite the existing marker"),
					() -> assertEquals(3L, rows));
		} finally {
			repository.shutDown();
		}
	}

	private static void seedSnapshot(Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(store.awaitSketchesReady(30, TimeUnit.SECONDS));
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:repeated-marker-commit:first"), P, VF.createLiteral(1));
			}
			assertTrue(store.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			estimator.persistIfDirty();
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L)
				.setBackgroundRawSamplingEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}
}
